  [99156] = { "Pattuglia di retroguardia", "Porta il Riptear's Heart alla Guardia della Morte Linnea.", "Maledizione! È arrivato un nuovo rapporto mentre eri di pattuglia. Un abominio rinnegato è stato avvistato mentre vagava nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ orientali, vicino alla ⟦Venomweb Vale=Valle Tela Venefica⟧.\n\nC'è qualcosa che non va. Gli abomini non oltrepassano il Bulwark inosservati.\n\nTieni la faccenda strettamente riservata. Detto questo, una creatura del genere non cadrà facilmente: ti serviranno alleati, se non vuoi diventare il suo prossimo pasto.\n\nPorta a termine il compito e sarai ricompensat<o/a> come si deve. Portami il suo cuore come prova dell'impresa.", "Hai risolto il nostro piccolo problema?", "Sei la prova dell'astuzia e della coordinazione che tutti i Reietti possiedono, qualcosa che il Flagello senza cervello non avrà mai.\n\nTi prego, accetta questo come ringraziamento per i tuoi sforzi, come promesso.", 0x889b08c3, 0x64da93a0, 0x08dcb58d, 0x45c20a1e, 0xc963fae0, "....." },
  [99191] = { "Una donazione di lana", nil, nil, "L'High Order al momento accetta donazioni di lana.\n\nUna donazione di sessanta pezze di lana ti varrà il pieno riconoscimento dell'High Order per la tua generosità. Sessanta pezze di lana dovrebbero bastare, per ora, alle necessità dell'High Order.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", nil, 0xaad71c6f, nil, nil, 0xec1c7e4f, nil, ".mm.m" },
